<section class="page-heading"><span class="eyebrow">CHĂM SÓC CUỘC TRÒ CHUYỆN</span><h1><?= e($title) ?></h1><p>Bình luận được hiển thị dưới dạng văn bản thuần. Ẩn bình luận gốc vẫn giữ các phản hồi đã duyệt.</p></section><nav class="filter-tabs" aria-label="Trạng thái bình luận"><?php foreach(['pending','approved','hidden'] as $s): ?><a class="<?= $status===$s?'selected':'' ?>" href="<?= e(url('admin/comments',['status'=>$s])) ?>"><?= e(label_status($s)) ?></a><?php endforeach ?></nav><div class="panel"><?php if(!$items): ?><div class="empty-state">Không có bình luận ở trạng thái này.</div><?php endif ?>
<?php foreach($items as $c): ?><article class="moderation-comment"><div class="comment-heading"><strong><?= e($c['user_name']) ?> <?= $c['parent_id']?'· Trả lời #'.(int)$c['parent_id']:'' ?></strong><?= badge($c['status']) ?></div><p class="plain-comment"><?= e($c['content']) ?></p><small>Bài: <?= e($c['title']) ?> · <?= e($c['created_at']) ?></small><div class="mt-3"><form class="d-flex gap-2" method="post" action="<?= e(url('admin/comments')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="version" value="<?= (int)$c['version'] ?>"><?php if($c['status']!=='approved'): ?><button class="btn btn-success btn-sm" name="status" value="approved">Duyệt hiển thị</button><?php endif ?><?php if($c['status']!=='hidden'): ?><button class="btn btn-outline-danger btn-sm" name="status" value="hidden">Ẩn bình luận</button><?php endif ?></form></div></article><?php endforeach ?></div>
<?php $pagerRoute='admin/comments';$pagerParams=['status'=>$status];require ROOT.'/app/Views/partials/pagination.php'; ?>
